<template><div><Button :loading="busy" @click="enrich">Suggest details</Button><Dialog v-model="show" title="Suggested details"><template #default><p v-if="error" role="alert">{{ error }}</p><p v-else-if="!rows.length">No matching details found.</p><dl v-else><template v-for="row in rows" :key="row.label"><dt class="mt-2 font-medium">{{ row.label }}</dt><dd>{{ row.value }}</dd></template></dl><p class="mt-4 text-sm text-ink-gray-5">Review suggestions and use Edit to apply them. Your saved details have not changed.</p></template></Dialog></div></template>
<script setup lang="ts">
import { ref } from "vue"; import { Button, Dialog, call } from "frappe-ui";
const props=defineProps<{name:string;kind:"customer"|"contact"}>();const show=ref(false);const busy=ref(false);const error=ref("");const rows=ref<any[]>([]);
async function enrich(){busy.value=true;error.value="";rows.value=[];try{const result=await call("helpdesk.api.capabilities.enrich_"+props.kind,{name:props.name});const item=result.company||result.person||{};for(const [key,label] of [["name","Name"],["fullName","Name"],["title","Job title"],["industry","Industry"],["location","Location"],["employeeCount","Employees"],["domain","Website"]]){if(item[key])rows.value.push({label,value:typeof item[key]==="string"?item[key]:JSON.stringify(item[key])});}}catch{error.value="Could not look up details. Check the work email or website domain.";}finally{busy.value=false;show.value=true;}}
</script>
